$_MODULE['<{priceandorder}prestashop>_settings_c9cc8cce247e49bae79f15173ce97354'] = 'Guardar';
$_MODULE['<{priceandorder}prestashop>_tutorial_cb59b87e00d11222bfd9159d0d23836f'] = 'Primeros pasos';
$_MODULE['<{priceandorder}prestashop>_tutorial_ea67abf8988cbc6b378a032f822801f8'] = 'Abra la pestaña Configuración e introduzca la(s) dirección(es) de correo que deben recibir las solicitudes de presupuesto.';
$_MODULE['<{priceandorder}prestashop>_tutorial_7f1b3b7557f81bb527614a601f1df990'] = 'Elija qué campos opcionales solicitar a los visitantes (dirección, teléfono, cantidad...).';
$_MODULE['<{priceandorder}prestashop>_tutorial_cc3b0858bf5fcf55dc3e1daae0076461'] = 'Vaya a Diseño > Posiciones en su administración y asegúrese de que Priceandorder esté activado en el hook \"Columna izquierda\" o \"Columna derecha\" para mostrar el formulario lateral, y en \"Pie de página\" para el botón flotante.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Envíe una solicitud de prueba desde su tienda y compruebe que llega a la pestaña Solicitudes de presupuesto y a su buzón de correo.';
$_MODULE['<{priceandorder}prestashop>_tutorial_9ffdb95250e26c7a6b468126ac7c75b0'] = 'Cómo funciona';
$_MODULE['<{priceandorder}prestashop>_tutorial_813ce2687d65c0253de66d80cddab8f3'] = 'El bloque lateral y el botón flotante comparten el mismo formulario; un visitante puede usar cualquiera de los dos.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bc9e9fef06497c843ddb85f457c24635'] = 'A los clientes que han iniciado sesión nunca se les pide su nombre o correo &mdash; los datos de su cuenta se utilizan automáticamente.';
$_MODULE['<{priceandorder}prestashop>_tutorial_fe920a7d738e80a23e8675183ec4450d'] = 'Cada envío se guarda en la pestaña Solicitudes de presupuesto incluso si el correo de notificación no se entrega, para que nada se pierda.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bd4b0999a932632905b77cd2fbc0a97c'] = 'La protección contra spam es automática: un campo trampa oculto y una breve comprobación de tiempo bloquean silenciosamente los envíos automatizados, y no se aceptan más de 5 solicitudes por hora del mismo visitante. No hay nada que un visitante real deba resolver.';
$_MODULE['<{priceandorder}prestashop>_tutorial_231cf4c70d866b616c21baddaeed0696'] = 'Solución de problemas';
$_MODULE['<{priceandorder}prestashop>_tutorial_958aae0a194da728c36d3e7221675a84'] = 'El formulario no aparece en la tienda.';
$_MODULE['<{priceandorder}prestashop>_tutorial_babc3ee2827d2d3ae2ea9f8800c92452'] = 'Vaya a Diseño > Posiciones en la administración, busque \"priceandorder\" y asegúrese de que esté vinculado a un hook de columna (lateral) o al hook de pie de página (botón flotante), y que su tema actual muestre realmente ese hook (algunos temas eliminan la columna izquierda/derecha).';
$_MODULE['<{priceandorder}prestashop>_tutorial_106e29c08b607e3b79c61dc35b0289a7'] = 'No estoy recibiendo los correos de solicitud de presupuesto.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0335b6ca536d6d636bdf088442b44790'] = 'Compruebe si hay errores tipográficos en la dirección del destinatario en Configuración, revise su carpeta de spam y confirme que el correo saliente funciona probando otro módulo o Parámetros avanzados > Correo electrónico. De todos modos, cada solicitud se guarda en la pestaña Solicitudes de presupuesto, así que siempre podrá encontrarla allí.';
$_MODULE['<{priceandorder}prestashop>_tutorial_487e540af0ce1574b40b98daaf9a704e'] = 'Un visitante dice que el formulario rechazó su envío.';
$_MODULE['<{priceandorder}prestashop>_tutorial_46ec8e9cec078e1824c2285289a9845a'] = 'Casi siempre se trata de la protección antispam automática: enviar el formulario antes de 3 segundos desde que se cargó la página, enviarlo más de una hora después de cargarse, o más de 5 solicitudes en una hora desde la misma conexión. Pídales que recarguen la página y lo intenten de nuevo.';
$_MODULE['<{priceandorder}prestashop>_tutorial_f9459c8296e5294ec5990a767724198b'] = 'Los enlaces de Términos y Condiciones / Política de Privacidad faltan o son incorrectos.';
$_MODULE['<{priceandorder}prestashop>_tutorial_13dabddb6263b6457635e4c5d2035082'] = 'Configúrelos explícitamente en Configuración. Si el enlace de Términos se deja vacío, se utiliza automáticamente la página CMS de Términos y Condiciones de su tienda; si el enlace de Privacidad se deja vacío, simplemente no se muestra.';
$_MODULE['<{priceandorder}prestashop>_tutorial_738cfeba525f1715b35cdbae92e826d9'] = 'Mi imagen promocional se ve estirada o es rechazada.';
$_MODULE['<{priceandorder}prestashop>_tutorial_a7821d5fcb146c5ad0b90884e504d314'] = 'Las subidas se limitan a archivos JPG, PNG, GIF o WEBP de hasta 4 MB y se redimensionan automáticamente para ajustarse a 400x280 px manteniendo sus proporciones, por lo que el archivo nunca se distorsiona.';
